        },
      });
    }
  }

  return res.status(200).json({ received: true });
}

async function handleSubscriptionUpdated(event: Stripe.Event) {
  const eventCreated = event.created;
  const {
    cancel_at,
    id,
    status,
    current_period_end,
    current_period_start,
    customer,
    items,
  } = event.data.object as Stripe.Subscription;

  const deletedEvent = await prisma.subscriptionEvent.findUnique({
    where: {
      subscriptionId: id,
    },
  });

  if (deletedEvent?.deleted && deletedEvent.eventCreated >= eventCreated) {
    return;
  }

  const subscription = await getBySubscriptionId(id);
  if (!subscription) {
    const teamExists = await getByCustomerId(customer as string);
    if (!teamExists) {
      return;
    }

    await handleSubscriptionCreated({
      ...event,
      type: 'customer.subscription.created',
    });
    return;
  }

  if (subscription.stripeEventTime > eventCreated) {
    return;
  }

  const priceId = items.data.length > 0 ? items.data[0].plan?.id : '';

  await updateStripeSubscription(id, {
    active: status === 'active',
    endDate: current_period_end
      ? new Date(current_period_end * 1000)
      : undefined,
    startDate: current_period_start
      ? new Date(current_period_start * 1000)
      : undefined,
    cancelAt: cancel_at ? new Date(cancel_at * 1000) : null,
    priceId,
    stripeEventTime: eventCreated,
  });
}

async function handleSubscriptionCreated(event: Stripe.Event) {
  const eventCreated = event.created;
  const { customer, id, current_period_start, current_period_end, items } =
    event.data.object as Stripe.Subscription;

  const deletedEvent = await prisma.subscriptionEvent.findUnique({
